from launch_common24 import *
j=base('launch_animal_systems_data','Animal systems: the evidence challenge','Audit a teaching model using mechanisms, calculations and limits','Use evidence about control, circulation and gas exchange to judge claims in an unfamiliar model.',6,'Summer C34 application of Topics 7–8. Original integrated practice linked to Pearson 7.13, 8.3–8.5B and 8.12. Fick-style comparisons are Biology-specific, not automatically Higher-only. No diagnosis or complete-topic coverage is claimed.',['Insulin helps regulate raised blood glucose.','Cardiac output equals heart rate multiplied by stroke volume.','Area, gradient and distance influence diffusion.'],['Calculate and compare pump output with units.','Use a controlled comparison to explain a diffusion prediction.','Separate a supported mechanism from a claim the data cannot establish.'],[('cardiac output','The volume of blood pumped by one ventricle per unit time.'),('stroke volume','The volume of blood pumped by one ventricle per beat.'),('controlled comparison','A comparison in which the factor of interest changes while relevant other factors are kept the same.'),('model limitation','Something a simplified representation does not include or cannot establish.'),('insulin','A pancreatic hormone involved in reducing raised blood glucose.'),('glycogen','A storage carbohydrate made from glucose.')])
j['sources'] += [source('NHLBI: How blood flows through the heart','https://www.nhlbi.nih.gov/health/heart/blood-flow','Used for the circulation and oxygen-transport pathway.'),source('NHLBI: What breathing does for the body','https://www.nhlbi.nih.gov/health/lungs/breathing-benefits','Used for alveolar exchange and oxygen transport.'),source('NIDDK: What is diabetes?','https://www.niddk.nih.gov/health-information/diabetes/overview/what-is-diabetes','Used for insulin, glucose and energy context. All numerical records are constructed classroom data, not patient measurements.')]
j['misconceptions']=[misconception('A faster heart rate always means greater cardiac output.','Stroke volume also matters; multiply both quantities.','Compare both columns before calculating.'),misconception('Twice the area always doubles diffusion rate.','That prediction requires the other relevant factors to be held constant.','Compare X with Y, where thickness also changes.'),misconception('A pump-output number proves that a tissue receives enough oxygen.','Adequacy also depends on oxygen content, distribution, exchange and tissue demand.','Ask which of those quantities was measured.'),misconception('Insulin is the fuel carried to cells.','Glucose is a fuel; insulin is a signal that affects target-tissue responses.','Label one signal arrow and one material arrow.')]
v1=visual('Oxygen supply is a linked pathway','Schematic pathway: ventilation replenishes alveolar air; oxygen diffuses into pulmonary blood; heart-driven circulation carries oxygen to tissue capillaries; oxygen diffuses towards cells down a gradient. Cells use oxygen in aerobic respiration. It is not a quantitative supply model.',[rect(50,110,390,135),text(75,130,340,95,'Ventilation\nReplenishes alveolar air',27,True,'center'),rect(555,110,390,135),text(580,130,340,95,'Lung exchange\nOxygen diffuses into blood',26,True,'center'),rect(555,325,390,150),text(580,345,340,105,'Circulation\nCarries oxygen towards\ntissue capillaries',26,True,'center'),rect(50,325,390,150),text(75,345,340,105,'Tissue exchange\nOxygen diffuses to cells\nfor aerobic respiration',26,True,'center'),line(453,175,540,175,True),line(750,260,750,310,True),line(540,395,455,395,True),text(50,495,900,45,'Each link has a different mechanism; one number cannot describe them all.',24)])
v2=bars('Constructed pump records: calculate both factors','Constructed teaching records. Pump A: 60 beats/min × 70 mL/beat = 4,200 mL/min = 4.2 L/min. Pump B: 90 × 60 = 5,400 mL/min = 5.4 L/min. These are not observations of pupils or diagnostic reference ranges.',['A','B'],[4.2,5.4],6,'Model pump output (L/min)')
v3=visual('Distinguish a hormone message from a transported fuel','Two related but distinct routes. Insulin released by pancreatic beta cells is carried in blood and signals responsive target tissues. Glucose is carried as a material; insulin promotes uptake in responsive tissues and glycogen storage in liver/muscle. The model does not imply all glucose uptake requires insulin.',[rect(45,120,270,125),text(65,142,230,85,'Pancreatic\nbeta cells',27,True,'center'),rect(650,120,305,125),text(670,137,265,100,'Responsive tissues\nReceive insulin signal',26,True,'center'),line(330,180,630,180,True,color=PURPLE),text(350,130,260,42,'Insulin in blood',26,True,'center'),rect(45,330,270,125,fill='#EEF3F7',stroke=BLUE),text(65,350,230,90,'Glucose\nin blood',27,True,'center'),rect(650,330,305,125,fill='#EEF3F7',stroke=BLUE),text(670,345,265,105,'Glucose uptake /\nglycogen storage\nare promoted',26,True,'center'),line(330,390,630,390,True,color=BLUE),text(335,425,290,40,'Glucose is a material',24,True,'center'),line(805,260,805,310,True,color=PURPLE),text(45,495,910,45,'Insulin is a signal; it is not converted into glycogen.',26,True)])
pumps=[['A','60','70'],['B','90','60']]
exchange=[['X','3','4','1'],['Y','6','4','2'],['Z','6','4','1']]
j['slides']=[slide('Opening',2,'Can the claim survive the evidence?',['A fictional teaching lab has three connected models.','Your job: calculate, explain and limit its claims.'],'Make clear this is a model audit, not a health test. A pupil can challenge a claim without proposing any treatment.'),slide('Retrieval',3,'Recover three mechanisms',['R1. What is cardiac output calculated from?','R2. Which way does net diffusion occur?','R3. Is insulin a signal or a glucose store?'],'R1 heart rate × stroke volume. R2 down a concentration gradient. R3 a hormone signal; glycogen is a storage carbohydrate.'),slide('I do',4,'Think across the oxygen pathway',['Name the job at each link.','An output number describes one link only.'],'Think aloud: “I can use pump output to compare volume per minute. I cannot turn it into oxygen delivery without oxygen content and distribution. I also need exchange and demand to judge adequacy.” Explain aerobic respiration in cells, not in the lungs.',visual=v1),slide('I do',3,'Calculate before judging',['A: 60 × 70 = 4,200 mL/min.','Convert: 4,200 ÷ 1,000 = 4.2 L/min.'],'Show beats cancelling in the units. B is 90 × 60 = 5,400 mL/min = 5.4 L/min. A has the larger stroke volume, but B has the greater output in these records.',visual=v2),slide('I do',3,'Keep signal and material separate',['Insulin changes responses in target tissues.','Glucose is transported and can be stored as glycogen.'],'Trace purple signal arrow and blue material arrow. After raised glucose, increased insulin can promote uptake and storage, helping glucose return towards its usual range. Do not claim every cell requires insulin for glucose entry.',visual=v3),slide('We do',3,'Choose a fair comparison',['W1. Which pair tests area alone?','W2. Which pair tests thickness alone?'],'X/Z changes area alone: predicted index doubles. Y/Z changes thickness alone: Z has half the thickness and twice the index. X/Y changes two factors and cannot isolate either effect.',table=table(['Case','Relative area','Relative gradient','Relative thickness'],exchange,'Constructed model: rate index = area × gradient ÷ thickness; same omitted constant.')),slide('We do',2,'Audit the headline',['W3. “B has a higher output, so every tissue definitely gets enough oxygen.”','Keep the supported part; reject the unsupported part.'],'Supported: B pumps a greater volume per minute in these records. Not established: adequacy for every tissue; oxygen content, distribution, exchange and demand were not measured. Ask pupils to name one needed piece of evidence.',visual=v1),slide('We do',2,'Test a tempting shortcut',['“Y has twice the area of X, so its index must be twice as large.”','Predict, calculate, then explain.'],'X = 3 × 4 / 1 = 12. Y = 6 × 4 / 2 = 12. Both area and thickness double, so effects cancel in this idealised rule. The result is a model prediction, not a clinical observation.',reveal='X and Y both have index 12. Two factors changed.'),slide('Hinge',3,'Which conclusion is fully supported?',['Select the claim that respects the evidence.'],'Correct option names the same relative model and unchanged factors. Reteach a comparison by circling the two identical columns.',options=[option('Z has twice X’s relative index because area doubles while gradient and thickness stay the same.',True,'The controlled comparison supports that prediction under the supplied rule.'),option('B proves that a pupil is fitter than another pupil.',False,'The records are constructed and do not measure pupils, fitness or health.'),option('Insulin is broken down into glycogen to provide a store.',False,'Glycogen is made from glucose; insulin is a hormone signal.')]),slide('You do',1,'Write a defensible evidence note',['Choose one route.','Include a calculation, a mechanism and a limit.'],'The same objective applies across routes. Supply read-aloud or calculator access as needed and record support.'),slide('You do',10,'Use the data; qualify the claim',['Cite a named record or controlled pair.','Explain what the model cannot establish.'],'Supported S1–S4, standard M1–M4 or stretch T1–T4. A correct number without units needs repair; a causal claim needs a comparison or mechanism.'),slide('Review',2,'Audience: ask for the missing evidence',['L1. Share one claim with a quiet partner or adult.','Audience asks: what would you need to measure next?'],'A useful next measure could be stroke volume under a defined condition, oxygen content, tissue blood distribution or a controlled exchange variable. Accept a focused question, not a vague “more data”.'),slide('Review',1,'Make one claim stronger',['Add a unit, a controlled comparison or a model limit.'],'Pupil records one revision. Ask whether the new evidence could distinguish two explanations.'),slide('Exit',1,'Three quick evidence checks',['E1. Calculate 80 beats/min × 50 mL/beat in L/min.','E2. Why is X/Y not an area-only test?','E3. Name one missing quantity for oxygen adequacy.'],'E1 4 L/min. E2 area and thickness both change. E3 demand, oxygen content, distribution or actual exchange. No medical interpretation is needed.'),slide('Exit',0,'Choose the next practice',['Units • controlled pairs • hormone roles • limits.'],'Shared exit minute; let pupils point to a next step and explain briefly.')]
j['pupilPages']=[page('Shared evidence | Constructed systems models','All records below are invented teaching data. They do not describe pupils or diagnose health.',[tb(['Pump','Heart rate (beats/min)','Stroke volume (mL/beat)'],pumps),txt('Pump output = heart rate × stroke volume. There are 1,000 mL in 1 L. Neither oxygen content nor tissue demand was measured.'),tb(['Exchange case','Relative area','Relative gradient','Relative thickness'],exchange),txt('Relative diffusion index = area × gradient ÷ thickness, using the same omitted constant. The rule is idealised and has no calibrated clinical unit.'),txt('Control case: glucose absorbed from the gut has raised blood glucose. Pancreatic beta cells release more insulin. Responsive tissues increase uptake and liver/muscle storage is promoted. This is a qualitative model, not treatment advice.'),response('W1–W3. Choose the fair pairs; then repair the “every tissue gets enough oxygen” headline.',3)]),page('Supported route | Build an evidence note','Use the shared page. Sentence starters: “The calculation shows…”; “This comparison keeps…”; “It does not show…”.',[response('S1. Calculate outputs for A and B in mL/min and L/min. Which is greater?',4),response('S2. Choose the area-only pair from X, Y and Z. Name the two unchanged factors and predict the relative effect.',3),response('S3. Explain how insulin differs from glucose and glycogen in the control case.',3),response('S4. Repair: “A higher pump output proves enough oxygen reaches every cell.” Keep what is supported and state one missing measurement.',4)]),page('Standard route | Audit three claims','Use mechanisms and data in every answer where relevant.',[response('M1. Calculate A and B outputs in L/min and the difference. Explain why comparing heart rate alone is unsafe as a general shortcut.',4),response('M2. Calculate indices for X, Y and Z. Explain why X and Y do not isolate an area effect.',4),response('M3. Explain the insulin response to raised blood glucose, distinguishing the hormone signal from the stored material.',4),response('M4. Trace oxygen from alveolar air to a tissue cell. Use this pathway to explain two limits of inferring oxygen adequacy from pump output alone.',4)]),page('Stretch route | Design the next comparison','Optional extension uses the same model; no Higher-only endocrine mechanism is required.',[response('T1. A pump C has 120 beats/min and 35 mL/beat. Compare its output with A and B. What does this show about using heart rate alone?',4),response('T2. Design an area-only comparison with X, using an area of 9. State the gradient, thickness and predicted relative index.',3),response('T3. The supplied model omits oxygen content and tissue demand. Explain how either could change the adequacy judgement even if output stayed the same.',4),response('T4. Write a concise advice note to the model’s designer: one supported conclusion, one unsupported claim and one specific extra measurement.',4)]),page('Exit and reflection | Evidence before certainty','Answer independently or explain to an adult who records your reasoning.',[response('E1. Calculate 80 beats/min × 50 mL/beat in L/min.',2),response('E2. Why is X/Y not an area-only test?',2),response('E3. Name one missing quantity needed to judge whether oxygen supply meets tissue demand.',2),response('L1. Record the audience’s evidence question and the revision it prompted.',4),choices('My next step',['Keep calculation units consistent.','Choose a controlled comparison.','Separate signal from material.','State what evidence cannot establish.'])])]
j['answers']=[qa('Retrieval','R1 cardiac output = heart rate × stroke volume. R2 net diffusion down a concentration gradient. R3 insulin is a hormone signal; glycogen is a store made from glucose.'),qa('We do and hinge','W1 X/Z varies area only; Z has twice X’s index. W2 Y/Z varies thickness only; Z has half Y’s thickness and twice its index. W3 B has greater volume output, but adequacy is unproven. X and Y both give index 12 because area and thickness both double. First hinge option is correct; the other options falsely infer pupil fitness or turn insulin into glycogen.'),qa('S1 / M1','A = 60 × 70 = 4,200 mL/min = 4.2 L/min. B = 90 × 60 = 5,400 mL/min = 5.4 L/min. Difference = 1.2 L/min. B is greater. Heart rate alone ignores stroke volume.'),qa('S2 / M2','Area-only pair X/Z: gradient 4 and thickness 1 are unchanged. X = 12, Y = 12, Z = 24. X/Y changes area and thickness together, so it cannot isolate one factor. Index units are relative, not calibrated physiological units.'),qa('S3 / M3','Raised glucose stimulates pancreatic beta cells to release insulin. Insulin signals responsive tissues and promotes uptake and glycogen storage in liver/muscle; blood glucose moves towards its usual range. Glucose is a transported material; glycogen is its storage carbohydrate. Some uptake is insulin-independent.'),qa('S4 / M4','Ventilation replenishes alveolar air; oxygen diffuses into pulmonary blood, is carried by circulation to tissue capillaries and diffuses towards cells, where it supports aerobic respiration. Pump output alone omits oxygen content, distribution, exchange performance and tissue demand. Any two explained limitations are valid.'),qa('T1','C = 120 × 35 = 4,200 mL/min = 4.2 L/min, equal to A and below B. C has the highest heart rate but not the highest output. Both factors matter.'),qa('T2','Keep gradient 4 and thickness 1; use area 9. Predicted index = 9 × 4 / 1 = 36, three times X. Other assumptions and the proportionality constant must also match.'),qa('T3','At the same output, less oxygen per unit blood could reduce oxygen delivery. Greater tissue oxygen demand could make the same delivery insufficient. These are conditional mechanisms; the supplied data do not measure either quantity or identify a person’s condition.'),qa('T4','Example: B has greater volume output than A, 5.4 versus 4.2 L/min. This does not establish adequate oxygen supply to every tissue. Measure oxygen content of the supplied blood and specify tissue demand to test that stronger claim. Accept another coherent conclusion/limit/measurement trio.'),qa('Exit and success','E1 80 × 50 = 4,000 mL/min = 4 L/min. E2 both area and thickness change. E3 oxygen content, distribution, exchange or tissue demand. Secure work combines an accurate calculation, a mechanism and a specific limit; reteach whichever link is missing.'),qa('L1','Accept a recorded evidence question and a meaningful revision, such as adding “under this model” or replacing an unsupported health conclusion with a specific output comparison.')]
j['teacherNotes'] += ['Interactive prediction–test–explain uses the same pump records and X/Y/Z cases as the printable sheet. Pupils can point to columns and calculate on paper without losing the scientific decision.','Do not invite diagnoses, personal fitness comparisons or medication advice. These are constructed teaching records with explicitly limited claims.','Optional stretch is about evidence and model design. Glucagon and other Higher-only endocrine mechanisms are not needed.']
j['interactive']=interactive('Systems evidence desk','Constructed classroom models: predict, test a claim, then explain its limit.',[step('Which pump has the greater output in these records?','B, after multiplying both factors.','A, because its stroke volume alone is larger.',v2,'B gives 5.4 L/min; A gives 4.2 L/min. Both heart rate and stroke volume contribute.','A’s greater stroke volume does not outweigh B’s greater heart rate in these records.'),step('Does a higher pump output prove enough oxygen reaches every tissue?','No; oxygen content, distribution and demand are also needed.','Yes; output alone establishes adequacy.',v1,'Output is a volume per minute. Adequacy requires information about oxygen and the receiving tissues.','The pathway contains exchange and distribution stages, and tissue demand was not measured.'),step('Which statement keeps signal and material separate?','Insulin signals; glucose can be stored as glycogen.','Insulin is converted into glycogen.',v3,'Insulin influences target-tissue responses; glycogen is made from glucose.','The hormone is not the carbohydrate material used to build glycogen.')])
save(j)
